compile.workshop:
variables {
    global:
        127: __overpyTranslationHelper__
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(__overpyTranslationHelper__, String Split(Custom String("0Blanc"), First Of(Null)));
    }
}

rule ("translation unicode boundary") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Big Message(Event Player, Value In Array(String Split(Custom String("ＴＬＥｒｒAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA界界界界界界界界界界{0}", Event Player), Global.__overpyTranslationHelper__), Absolute Value(Index Of Array Value(Global.__overpyTranslationHelper__, String Split(Color(White), Empty Array)))));
    }
}

